def decodificar(mac):
    primero = int(mac.split(':')[0], 16)
    return {
        'binario del primer byte': format(primero, '08b'),
        'grupo (multicast o difusión)': bool(primero & 0b01),
        'administrada localmente': bool(primero & 0b10),
        'OUI (3 primeros bytes)': mac[:8].upper(),
    }

for m in ['02:fc:00:00:00:01', 'ff:ff:ff:ff:ff:ff', '01:00:5e:00:00:16', 'b8:27:eb:12:34:56']:
    print(m)
    for k, v in decodificar(m).items():
        print('   ', k + ':', v)

// Un switch de 4 puertos que aprende. Cada trama llega por un puerto con una MAC de origen y una de destino.
const tabla = {};                       // MAC -> puerto donde se la vio por última vez
const PUERTOS = [1, 2, 3, 4];

function recibir(puerto, origen, destino) {
  tabla[origen] = puerto;               // 1) aprender: el origen está del lado de este puerto
  let accion;
  if (destino === 'ff:ff:ff:ff:ff:ff' || !(destino in tabla)) {
    const salidas = PUERTOS.filter(p => p !== puerto);
    accion = 'inunda por los puertos ' + salidas.join(', ');   // 2) difusión o destino desconocido
  } else if (tabla[destino] === puerto) {
    accion = 'descarta (el destino está del mismo lado)';
  } else {
    accion = 'reenvía solo por el puerto ' + tabla[destino];   // 3) destino conocido
  }
  console.log(`puerto ${puerto}: ${origen.slice(-2)} -> ${destino.slice(-2)}  ${accion}`);
}

const A = '02:00:00:00:00:0a', B = '02:00:00:00:00:0b', C = '02:00:00:00:00:0c';
recibir(1, A, B);                       // B todavía no habló
recibir(2, B, A);                       // ahora se aprende B; A ya se conocía
recibir(1, A, B);                       // los dos conocidos
recibir(3, C, 'ff:ff:ff:ff:ff:ff');     // difusión
recibir(1, A, C);                       // C se aprendió recién
